from dataclasses import dataclass
from enum import Enum
class EvaluationDecision(str, Enum): APPROVED="APPROVED"; REVISION_REQUIRED="REVISION_REQUIRED"; REJECTED="REJECTED"
class Severity(str, Enum): INFO="INFO"; REVISION="REVISION"; REJECT="REJECT"
class ComplianceFlag(str, Enum):
    MISSING_DISCLOSURE="MISSING_DISCLOSURE"; UNKNOWN_EVIDENCE="UNKNOWN_EVIDENCE"; CROSS_BRIEF_EVIDENCE="CROSS_BRIEF_EVIDENCE"; CROSS_CANDIDATE_EVIDENCE="CROSS_CANDIDATE_EVIDENCE"; UNSUPPORTED_ECONOMICS="UNSUPPORTED_ECONOMICS"; FABRICATED_DISCOUNT="FABRICATED_DISCOUNT"; MISLEADING_URGENCY="MISLEADING_URGENCY"; SCARCITY_CLAIM="SCARCITY_CLAIM"; GUARANTEED_INCOME="GUARANTEED_INCOME"; GUARANTEED_RESULTS="GUARANTEED_RESULTS"; FAKE_TESTIMONIAL="FAKE_TESTIMONIAL"; UNSUPPORTED_CAPABILITY="UNSUPPORTED_CAPABILITY"; UNSUPPORTED_PRICE="UNSUPPORTED_PRICE"; UNSUPPORTED_TRIAL="UNSUPPORTED_TRIAL"; UNSAFE_CTA="UNSAFE_CTA"; UNGROUNDED_CLAIM="UNGROUNDED_CLAIM"
EVALUATOR_VERSION="content-evaluator-v1"; POLICY_VERSION="affiliate-content-policy-v1"
@dataclass(frozen=True)
class ClaimEvaluationResult: claim_text:str; source_evidence_ids:tuple[str,...]; grounded:bool; flags:tuple[str,...]; severity:str; reason:str
@dataclass(frozen=True)
class ContentEvaluationResult: evaluation_id:str; decision:str; approved:bool; overall_score:int
